public class InnerConnectionTypeClientCredentialsPropertiesFactory(Action<Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties>
{

    internal InnerConnectionTypeConnectorPropertyFactory ScopeFactory { get; set; }

    internal InnerConnectionTypeSecretConnectorPropertyFactory ClientSecretFactory { get; set; }

    internal InnerConnectionTypeConnectorPropertyFactory TokenUrlFactory { get; set; }

    internal InnerConnectionTypeSecretConnectorPropertyFactory ClientIdFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties Create()
    {
        var clientCredentialsPropertiesResult = CreateClientCredentialsProperties();
        factoryAction?.Invoke(clientCredentialsPropertiesResult);

        return clientCredentialsPropertiesResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties CreateClientCredentialsProperties()
    {
        var clientCredentialsPropertiesResult = new Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties();

        return clientCredentialsPropertiesResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.ClientCredentialsProperties result)
    {
        base.CreateChildren(result);

        result.Scope ??= ScopeFactory?.Build();
        result.ClientSecret ??= ClientSecretFactory?.Build();
        result.TokenUrl ??= TokenUrlFactory?.Build();
        result.ClientId ??= ClientIdFactory?.Build();
    }

} // End Of Class

